// Shared by server and client. A region decides which markets' raw customer evidence a viewer can see.
export const MARKETS = ["US", "EU", "CN", "ROW"] as const;
export type Market = (typeof MARKETS)[number];
export type RegionCode = Market | "ALL";

export const REGIONS: { code: RegionCode; label: string; role: string }[] = [
  { code: "US", label: "United States", role: "Market product manager" },
  { code: "EU", label: "Europe", role: "Market product manager" },
  { code: "CN", label: "China", role: "Market product manager" },
  { code: "ROW", label: "Rest of World", role: "Market product manager" },
  { code: "ALL", label: "All markets", role: "Head of product" },
];

export const MARKET_LABEL: Record<string, string> = {
  US: "United States",
  EU: "Europe",
  CN: "China",
  ROW: "Rest of World",
  ALL: "All markets",
};

export const DEFAULT_REGION: RegionCode = "US";
export const REGION_COOKIE = "pmw_region";

export function isRegion(v: unknown): v is RegionCode {
  return typeof v === "string" && REGIONS.some((r) => r.code === v);
}

export function marketsFor(region: RegionCode): Market[] {
  return region === "ALL" ? [...MARKETS] : [region];
}

import Database from "better-sqlite3";
import path from "node:path";

// The pipeline writes this file: `cd pipeline && uv run pmw build`.
const DB_PATH = process.env.PMW_DB ?? path.join(process.cwd(), "..", "db", "pmw.sqlite");

const g = globalThis as unknown as { __pmwDb?: Database.Database };

export function db(): Database.Database {
  if (!g.__pmwDb) {
    const d = new Database(DB_PATH, { fileMustExist: true });
    d.pragma("journal_mode = WAL");
    g.__pmwDb = d;
  }
  return g.__pmwDb;
}

export function parse<T>(json: string | null | undefined, fallback: T): T {
  if (!json) return fallback;
  try {
    return JSON.parse(json) as T;
  } catch {
    return fallback;
  }
}

export function nowIso(): string {
  return new Date().toISOString().replace(/\.\d{3}Z$/, "+00:00");
}

// Mirrors the SQLite schema in pipeline/pmw/db.py. Keep the two in sync.

export type Quadrant = "act" | "validate" | "monitor" | "park";
export type Status = "proposed" | "approved" | "rejected" | "validate" | "edited";

export type Factor = { value: number; weight: number; note: string };
export type Factors = Record<string, Factor>;

export type SurveyRow = {
  market: string;
  variant: string | null;
  study: "US_2025" | "CN_EU_2025";
  attribute: string;
  mean: number;
  scale: 7 | 10;
  bottom3: number | null;
  top2: number | null;
  gap: number;
};

export type Conflict = { vehicle: string; attribute: string; cn: number; eu: number; delta: number };

export type Challenge = { issues: { penalty: number; text: string }[]; revised_confidence: number };

export type Requirement = {
  id: string;
  vehicle: string;
