/* Design tokens. Visual language follows bmw.de: photography first, light body type,
   uppercase bold headlines, square buttons, one blue. Change colours here, not in components. */
@theme {
  --font-sans: var(--font-albert), Arial, Helvetica, sans-serif;
  --font-mono: ui-monospace, "SF Mono", Menlo, monospace;

  --color-blue: #1c69d4;
  --color-blue-dark: #0653b6;
  --color-ink: #262626;
  --color-ink-2: #4d4d4d;
  --color-ink-3: #8e8e8e;
  --color-line: #e4e4e4;
  --color-mist: #f5f5f5;
  --color-night: #0d0f12;

  --color-act: #1f7a4d;
  --color-act-soft: #e3f2ea;
  --color-validate: #b86e00;
  --color-validate-soft: #fbf0dc;
  --color-monitor: #1c69d4;
  --color-monitor-soft: #e6effb;
  --color-park: #6f6f6f;
  --color-park-soft: #efefef;
  --color-danger: #c4302b;
