  --animate-settle: settle 1.4s cubic-bezier(0.16, 1, 0.3, 1) both;
}

@keyframes rise {
  from { opacity: 0; transform: translateY(28px); }
  to { opacity: 1; transform: none; }
}
@keyframes settle {
  from { transform: scale(1.08); }
  to { transform: scale(1); }
}

html { color-scheme: light; }
body {
  background: #fff;
  color: var(--color-ink);
