import Link from "next/link";
import { Header } from "@/components/Header";
import { getViewer, listVehicles } from "@/lib/gate";

export const dynamic = "force-dynamic";

const fmt = (n: number) => n.toLocaleString("en-US");

const STEPS = [
  { title: "Customer voice", text: "10,128 comments, surveys, sales and price lists, cleaned into one evidence base." },
  { title: "Signals and root causes", text: "Recurring complaints, unmet needs and competitor pressure, grouped and explained." },
  { title: "Priority and confidence", text: "Two separate scores from transparent formulas, never from the model alone." },
  { title: "Product manager decides", text: "Approve, edit, reject, challenge or ask for validation. Every step is logged." },
];

export default async function Home() {
  const viewer = await getViewer();
  const vehicles = listVehicles(viewer);
  // Deep demo vehicle first in the lane order the sketch uses: 1, 5, 7.
  const lanes = ["F70", "G60", "G70"].map((c) => vehicles.find((v) => v.code === c)!).filter(Boolean);

  return (
    <main className="flex-1">
      <section className="relative h-[max(620px,min(92vh,960px))] bg-night text-white">
        <Header viewer={viewer} variant="overlay" />
        <div className="grid h-full grid-cols-1 md:grid-cols-3">
          {lanes.map((v, i) => (
            <article
              key={v.code}
              className="group relative isolate overflow-hidden border-white/15 md:border-r last:border-r-0 animate-rise"
              style={{ animationDelay: `${i * 120}ms` }}
            >
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img
                src={v.image}
                alt={`${v.name}, front three-quarter view`}
                className={`absolute inset-0 -z-10 h-full w-full object-cover transition-transform duration-700 group-hover:scale-[1.03] animate-settle ${v.available ? "" : "grayscale brightness-50"}`}
                style={{ animationDelay: `${i * 120}ms` }}
              />
              <div className="absolute inset-0 -z-10 bg-gradient-to-t from-black/85 via-black/25 to-black/45" />
              <div className="flex h-full flex-col justify-end gap-4 p-6 pb-10 sm:p-10">
                <p className="text-[13px] font-medium uppercase tracking-[0.14em] text-white/75">{v.code} · Next generation</p>
                <h2 className="headline text-[34px] sm:text-[40px]">{v.name}</h2>
                {v.available ? (
                  <dl className="grid grid-cols-2 gap-x-6 gap-y-1 text-[14px] text-white/85">
                    <div><dt className="text-white/60">Customer comments</dt><dd className="font-medium text-white tabular-nums">{fmt(v.comments)}</dd></div>
                    <div><dt className="text-white/60">Sold in 2025</dt><dd className="font-medium text-white tabular-nums">{fmt(v.sales2025)}</dd></div>
                    <div><dt className="text-white/60">Requirements</dt><dd className="font-medium text-white tabular-nums">{v.requirements}</dd></div>
                    <div><dt className="text-white/60">Awaiting decision</dt><dd className="font-medium text-white tabular-nums">{v.awaiting}</dd></div>
                  </dl>
                ) : (
                  <p className="text-[15px] text-white/80">Not sold in {viewer.label}, so there is no evidence to review here.</p>
                )}
                {v.thin && (
                  <p className="border-l-2 border-validate pl-3 text-[14px] text-white/90">
                    Thin evidence: no customer comments from {viewer.label}. Requirements rest on survey means only.
                  </p>
                )}
                <div className="pt-2">
                  {v.available ? (
                    <Link href={`/vehicles/${v.code}`} className="btn-primary">Open requirements</Link>
                  ) : (
                    <span className="btn-ghost-light pointer-events-none opacity-60">Not available in your region</span>
                  )}
                </div>
              </div>
            </article>
          ))}
        </div>
      </section>

      <section className="container-x py-20">
        <div className="mx-auto max-w-[720px] text-center">
          <h1 className="headline text-[32px] sm:text-[40px]">What should the next generation offer?</h1>
          <p className="mt-4 text-[17px] text-ink-2">
            Product Minds on Wheels turns customer evidence into requirements a product manager can defend:
            every claim links to its source, and every decision stays with a person.
          </p>
        </div>
        <ol className="mt-14 grid gap-px bg-line sm:grid-cols-2 lg:grid-cols-4">
          {STEPS.map((s, i) => (
            <li key={s.title} className="flex flex-col gap-3 bg-white p-8">
              <span className="text-[13px] font-medium tabular-nums text-blue">Step {i + 1}</span>
              <h3 className="text-[22px] font-light leading-tight">{s.title}</h3>
              <p className="text-[14px] text-ink-2">{s.text}</p>
            </li>
          ))}
        </ol>
        <div className="mt-12 flex flex-wrap justify-center gap-4">
          <Link href="/vehicles/G70" className="btn-primary">Start with the 7 Series</Link>
          <Link href="/audit" className="btn-outline">View the audit trail</Link>
        </div>
      </section>

      <footer className="border-t border-line">
        <div className="container-x flex flex-wrap justify-between gap-4 py-8 text-[13px] text-ink-3">
          <span>Product Minds on Wheels · EHL Grand Finale 2026 · BMW challenge prototype</span>
          <span>Vehicle photography from the BMW price lists provided for the hackathon.</span>
        </div>
      </footer>
    </main>
  );
}

import Link from "next/link";
import { QUADRANT, STATUS_LABEL, type AuditEvent, type Factors, type Quadrant, type Requirement, type Status } from "@/lib/types";

const Q_STYLE: Record<Quadrant, string> = {
  act: "bg-act-soft text-act",
  validate: "bg-validate-soft text-validate",
  monitor: "bg-monitor-soft text-monitor",
  park: "bg-park-soft text-park",
};

export function QuadrantBadge({ q }: { q: Quadrant }) {
  return <span className={`inline-flex h-6 items-center px-2 text-[12px] font-semibold uppercase tracking-[0.06em] ${Q_STYLE[q]}`}>{QUADRANT[q].label}</span>;
}

const S_STYLE: Record<Status, string> = {
  proposed: "border border-line text-ink-2",
  edited: "bg-validate-soft text-validate",
  approved: "bg-act text-white",
  rejected: "bg-danger-soft text-danger",
  validate: "bg-validate text-white",
};

export function StatusBadge({ s }: { s: Status }) {
  return <span className={`inline-flex h-6 items-center px-2 text-[12px] font-medium ${S_STYLE[s]}`}>{STATUS_LABEL[s]}</span>;
}

export function ScorePair({ r, size = "sm" }: { r: Pick<Requirement, "priority" | "confidence">; size?: "sm" | "lg" }) {
  const big = size === "lg";
  return (
    <div className={`flex ${big ? "gap-8" : "gap-4"} tabular-nums`}>
      <div>
        <div className={big ? "eyebrow" : "text-[11px] uppercase tracking-[0.1em] text-ink-3"}>Priority</div>
        <div className={big ? "text-[44px] font-light leading-none" : "text-[20px] font-medium leading-none"}>{r.priority}</div>
      </div>
      <div>
        <div className={big ? "eyebrow" : "text-[11px] uppercase tracking-[0.1em] text-ink-3"}>Confidence</div>
        <div className={big ? "text-[44px] font-light leading-none" : "text-[20px] font-medium leading-none"}>{r.confidence}</div>
      </div>
    </div>
  );
}

export function FactorBars({ factors, labels }: { factors: Factors; labels: Record<string, string> }) {
  return (
    <ul className="flex flex-col gap-3">
      {Object.entries(factors).map(([k, f]) => (
        <li key={k} className="grid grid-cols-[1fr_auto] gap-x-3 gap-y-1 text-[13px]">
          <span className="font-medium text-ink">{labels[k] ?? k}</span>
          <span className="tabular-nums text-ink-3">{Math.round(f.value * 100)} · weight {Math.round(f.weight * 100)}%</span>
          <span className="col-span-2 h-1.5 bg-mist"><span className="block h-full bg-blue" style={{ width: `${Math.round(f.value * 100)}%` }} /></span>
          <span className="col-span-2 text-[12px] text-ink-3">{f.note}</span>
        </li>
      ))}
    </ul>
  );
}

/** Priority (x) vs confidence (y). Threshold lines split the four decision quadrants. */
export function Matrix({ items, thresholds, vehicle, selected, size = 520 }: {
  items: Requirement[];
  thresholds: { priority: number; confidence: number };
  vehicle: string;
  selected?: string;
  size?: number;
}) {
  const pad = 44;
  const w = size, h = size * 0.78;
  const x = (p: number) => pad + (p / 100) * (w - pad - 12);
  const y = (c: number) => h - pad - (c / 100) * (h - pad - 12);
  const tx = x(thresholds.priority), ty = y(thresholds.confidence);
  const zone = (q: Quadrant, x1: number, y1: number, x2: number, y2: number, lx: number, ly: number, anchor: "start" | "end") => (
    <g key={q}>
      <rect x={x1} y={y1} width={x2 - x1} height={y2 - y1} className={{ act: "fill-act-soft", validate: "fill-validate-soft", monitor: "fill-monitor-soft", park: "fill-park-soft" }[q]} />
      <text x={lx} y={ly} textAnchor={anchor} className="fill-ink-2 text-[11px] font-semibold uppercase tracking-[0.08em]">{QUADRANT[q].label}</text>
    </g>
  );
  return (
    <svg viewBox={`0 0 ${w} ${h}`} className="w-full max-w-full" role="img" aria-label="Decision matrix: priority against confidence">
      {zone("monitor", x(0), y(100), tx, ty, x(0) + 8, y(100) + 16, "start")}
      {zone("act", tx, y(100), x(100), ty, x(100) - 8, y(100) + 16, "end")}
      {zone("park", x(0), ty, tx, y(0), x(0) + 8, y(0) - 8, "start")}
      {zone("validate", tx, ty, x(100), y(0), x(100) - 8, y(0) - 8, "end")}
      <line x1={x(0)} y1={y(0)} x2={x(100)} y2={y(0)} className="stroke-ink-3" />
      <line x1={x(0)} y1={y(0)} x2={x(0)} y2={y(100)} className="stroke-ink-3" />
      {[0, 25, 50, 75, 100].map((t) => (
        <g key={t}>
          <text x={x(t)} y={y(0) + 16} textAnchor="middle" className="fill-ink-3 text-[10px] tabular-nums">{t}</text>
          <text x={x(0) - 8} y={y(t) + 3} textAnchor="end" className="fill-ink-3 text-[10px] tabular-nums">{t}</text>
        </g>
      ))}
      <text x={(x(0) + x(100)) / 2} y={h - 6} textAnchor="middle" className="fill-ink-2 text-[11px]">Priority →</text>
      <text x={12} y={(y(0) + y(100)) / 2} textAnchor="middle" transform={`rotate(-90 12 ${(y(0) + y(100)) / 2})`} className="fill-ink-2 text-[11px]">Confidence →</text>
      {items.map((r) => {
        const on = r.id === selected;
        return (
          <Link key={r.id} href={`/vehicles/${vehicle}?req=${r.id}`}>
            <g className="cursor-pointer">
              <title>{`${r.id} · ${r.title} · P${r.priority} C${r.confidence}`}</title>
              <circle cx={x(r.priority)} cy={y(r.confidence)} r={on ? 9 : 6} className={on ? "fill-ink stroke-white" : "fill-blue stroke-white"} strokeWidth={2} />
              <text x={x(r.priority) + 10} y={y(r.confidence) + 4} className={`text-[10px] tabular-nums ${on ? "fill-ink font-semibold" : "fill-ink-2"}`}>{r.id.slice(-3)}</text>
            </g>
          </Link>
        );
      })}
    </svg>
  );
}

const ACTOR_DOT: Record<string, string> = { ai: "bg-blue", pm: "bg-validate", system: "bg-ink-3" };

export function AuditTimeline({ events }: { events: AuditEvent[] }) {
  if (!events.length) return <p className="text-[14px] text-ink-3">No events yet.</p>;
  return (
    <ol className="relative flex flex-col">
      {events.map((e) => (
        <li key={e.id} className="relative grid grid-cols-[132px_14px_1fr] gap-3 py-2 text-[13px]">
          <time className="pt-0.5 text-right font-mono text-[11.5px] text-ink-3" dateTime={e.ts}>
            {new Date(e.ts).toLocaleString("en-GB", { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit", second: "2-digit" })}
          </time>
          <span className={`mt-1.5 h-2.5 w-2.5 rounded-full ${ACTOR_DOT[e.actor_type] ?? "bg-ink-3"}`} aria-hidden="true" />
          <div>
            <span className="font-semibold text-ink">{e.actor}</span> <span className="text-ink-2">{e.action}</span>
            {(e.before !== null || e.after !== null) && (
              <div className="mt-0.5 text-ink-2">
                {e.before !== null && <span className="line-through decoration-ink-3/60">{e.before}</span>}
                {e.before !== null && e.after !== null && <span className="px-1.5 text-ink-3">→</span>}
                {e.after !== null && <span>{e.after}</span>}
              </div>
            )}
            {e.rationale && <div className="mt-0.5 italic text-ink-3">“{e.rationale}”</div>}
          </div>
        </li>
      ))}
    </ol>
  );
}

export function Section({ title, aside, children }: { title: string; aside?: React.ReactNode; children: React.ReactNode }) {
  return (
    <section className="card p-6">
      <div className="mb-4 flex items-baseline justify-between gap-4">
        <h3 className="eyebrow">{title}</h3>
        {aside && <div className="text-[12px] text-ink-3">{aside}</div>}
      </div>
      {children}
    </section>
  );
}

"use client";

import { useRouter } from "next/navigation";
import { useState, useTransition } from "react";
import type { Requirement } from "@/lib/types";

type Mode = null | "reject" | "validate" | "edit" | "approve" | "challenge";

const PROMPT: Record<Exclude<Mode, null>, { label: string; placeholder: string; required: boolean; submit: string }> = {
  approve: { label: "Note (optional)", placeholder: "Why this goes into the next generation", required: false, submit: "Confirm approval" },
  reject: { label: "Reason", placeholder: "Why this should not shape the next generation", required: true, submit: "Confirm rejection" },
  validate: { label: "What needs validating?", placeholder: "e.g. Check China customer clinic before deciding", required: true, submit: "Request validation" },
  edit: { label: "Reason for the edit", placeholder: "What you changed and why", required: true, submit: "Save edit" },
  challenge: { label: "What do you doubt? (optional)", placeholder: "e.g. Is this only a US problem?", required: false, submit: "Run the challenge" },
};

/** Approve, validate first, edit, reject, challenge. Posts to /api/requirements/[id] and refreshes the page. */
export function DecisionActions({ r }: { r: Requirement }) {
  const router = useRouter();
  const [mode, setMode] = useState<Mode>(null);
  const [why, setWhy] = useState("");
  const [fields, setFields] = useState({ title: r.title, requirement: r.requirement, customer_need: r.customer_need ?? "" });
  const [error, setError] = useState<string | null>(null);
  const [pending, start] = useTransition();

  async function send(action: string) {
    setError(null);
    const res = await fetch(`/api/requirements/${r.id}`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ action, rationale: why, fields: action === "edit" ? fields : undefined }),
    });
    const data = (await res.json()) as { ok: boolean; error?: string };
    if (!data.ok) return setError(data.error ?? "Something went wrong.");
    setMode(null);
    setWhy("");
    start(() => router.refresh());
  }

  const decided = r.status === "approved" || r.status === "rejected";

  return (
    <div className="flex flex-col gap-3">
      <div className="flex flex-wrap gap-2">
        {decided ? (
          <button className="btn-outline btn-sm" onClick={() => send("reopen")} disabled={pending}>Reopen</button>
        ) : (
          <>
            <button className="btn-primary btn-sm" onClick={() => setMode("approve")} disabled={pending}>Approve</button>
            <button className="btn-outline btn-sm" onClick={() => setMode("validate")} disabled={pending}>Validate first</button>
            <button className="btn-outline btn-sm" onClick={() => setMode("edit")} disabled={pending}>Edit</button>
            <button className="btn-outline btn-sm" onClick={() => setMode("reject")} disabled={pending}>Reject</button>
          </>
        )}
        <button
          className="btn btn-sm border border-blue text-blue hover:bg-blue hover:text-white"
          onClick={() => setMode("challenge")}
          disabled={pending || r.challenged}
          title={r.challenged ? "Already challenged" : "Ask the AI what could make this wrong"}
        >
          {r.challenged ? "Challenged" : "Challenge"}
        </button>
      </div>

      {mode && (
        <form
          className="flex flex-col gap-3 border border-line bg-mist p-4"
          onSubmit={(e) => { e.preventDefault(); send(mode); }}
        >
          {mode === "edit" && (
            <>
              <label className="flex flex-col gap-1 text-[13px] font-medium">Title
                <input id="edit-title" className="border border-line bg-white px-3 py-2 font-light" value={fields.title} onChange={(e) => setFields({ ...fields, title: e.target.value })} />
              </label>
              <label className="flex flex-col gap-1 text-[13px] font-medium">Customer need
                <textarea id="edit-need" rows={2} className="border border-line bg-white px-3 py-2 font-light" value={fields.customer_need} onChange={(e) => setFields({ ...fields, customer_need: e.target.value })} />
              </label>
              <label className="flex flex-col gap-1 text-[13px] font-medium">Requirement
                <textarea id="edit-req" rows={3} className="border border-line bg-white px-3 py-2 font-light" value={fields.requirement} onChange={(e) => setFields({ ...fields, requirement: e.target.value })} />
              </label>
            </>
          )}
          <label className="flex flex-col gap-1 text-[13px] font-medium">
            {PROMPT[mode].label}
            <input
              id="decision-why"
              autoFocus
              className="border border-line bg-white px-3 py-2 font-light"
              placeholder={PROMPT[mode].placeholder}
              value={why}
              onChange={(e) => setWhy(e.target.value)}
              required={PROMPT[mode].required}
            />
          </label>
          {error && <p className="text-[13px] text-danger">{error}</p>}
          <div className="flex gap-2">
            <button type="submit" className="btn-primary btn-sm" disabled={pending}>{PROMPT[mode].submit}</button>
            <button type="button" className="btn-outline btn-sm" onClick={() => { setMode(null); setError(null); }}>Cancel</button>
          </div>
          <p className="text-[12px] text-ink-3">Recorded in the audit trail with your region and the time.</p>
        </form>
      )}
      {!mode && error && <p className="text-[13px] text-danger">{error}</p>}
    </div>
  );
}

import type { Viewer } from "@/lib/gate";
import { MARKET_LABEL } from "@/lib/regions";
import { POWERTRAIN_LABEL, QUADRANT, SOURCE_LABEL, type AuditEvent, type Quote, type Requirement } from "@/lib/types";
import { DecisionActions } from "./DecisionActions";
import { AuditTimeline, FactorBars, Matrix, QuadrantBadge, ScorePair, Section, StatusBadge } from "./ui";

const PENDING = "Pending AI analysis. Run the pipeline with --llm to fill this step.";

function Ladder({ r }: { r: Requirement }) {
  const steps = [
    { k: "Customer voice", v: r.customer_voice },
    { k: "Signal", v: r.signal_text },
    { k: "Root cause", v: r.root_cause },
    { k: "Customer need", v: r.customer_need },
    { k: "Requirement", v: r.requirement },
  ];
  return (
    <ol className="flex flex-col">
      {steps.map((s, i) => (
        <li key={s.k} className="relative grid grid-cols-[28px_1fr] gap-4 pb-5 last:pb-0">
          {i < steps.length - 1 && <span className="absolute left-[13px] top-7 bottom-0 w-px bg-line" aria-hidden="true" />}
          <span className={`grid h-7 w-7 place-items-center rounded-full text-[12px] font-semibold tabular-nums ${i === steps.length - 1 ? "bg-blue text-white" : "border border-ink-3 text-ink-2"}`}>{i + 1}</span>
          <div>
            <div className="eyebrow">{s.k}</div>
            <p className={`mt-1 text-[15px] ${s.v ? (i === steps.length - 1 ? "font-normal text-ink" : "text-ink-2") : "italic text-ink-3"}`}>{s.v ?? PENDING}</p>
          </div>
        </li>
      ))}
    </ol>
  );
}

function QuoteItem({ q }: { q: Quote }) {
  const strong = q.severity === "serious" || q.severity === "very serious";
  return (
    <li className={`border-l-2 pl-4 ${q.role === "contradicts" ? "border-act" : strong ? "border-danger" : "border-line"}`}>
      <p className="text-[15px] text-ink">“{q.text.length > 420 ? q.text.slice(0, 420) + "…" : q.text}”</p>
      <p className="mt-1 flex flex-wrap gap-x-3 text-[12px] text-ink-3">
        <span className="font-mono text-blue">{q.id}</span>
        <span>{SOURCE_LABEL[q.source] ?? q.source}</span>
        <span>{MARKET_LABEL[q.market] ?? q.market}{q.country && q.country !== q.market ? ` (${q.country})` : ""}</span>
        {q.powertrain && <span>{POWERTRAIN_LABEL[q.powertrain] ?? q.powertrain}</span>}
        {q.severity && <span>{q.severity} problem</span>}
      </p>
    </li>
  );
}

export function DecisionCard({ r, quotes, hidden, events, labels, thresholds, viewer, siblings }: {
  r: Requirement;
  quotes: Quote[];
  hidden: Record<string, number>;
  events: AuditEvent[];
  labels: Record<string, string>;
  thresholds: { priority: number; confidence: number };
  viewer: Viewer;
  siblings: Requirement[];
}) {
  const supports = quotes.filter((q) => q.role === "supports");
  const contradicts = quotes.filter((q) => q.role === "contradicts");
  const hiddenTotal = Object.values(hidden).reduce((a, b) => a + b, 0);
  const originalConfidence = events.find((e) => e.field === "confidence")?.before;

  return (
    <article className="flex flex-col gap-6">
      <header className="flex flex-col gap-4">
        <div className="flex flex-wrap items-center gap-2 text-[13px] text-ink-3">
          <span className="font-mono text-ink-2">{r.id}</span>
          <QuadrantBadge q={r.quadrant} />
          <StatusBadge s={r.status} />
          <span>· {r.generated_by === "template" ? "Template draft" : `Drafted by ${r.generated_by.replace("llm:", "")}`}</span>
          <span>· Evidence from {r.markets.map((m) => MARKET_LABEL[m] ?? m).join(", ")}</span>
        </div>
        <h1 className="text-[30px] font-light leading-tight sm:text-[36px]">{r.title}</h1>
        <DecisionActions r={r} />
      </header>

      {r.challenged && (
        <section className="border border-blue bg-monitor-soft p-6">
          <h3 className="eyebrow text-blue">Challenge result</h3>
          <p className="mt-2 text-[15px]">
            The red-team check found {r.challenge.issues.length} issue{r.challenge.issues.length === 1 ? "" : "s"}.
            Confidence moved from <b className="tabular-nums">{originalConfidence ?? "?"}</b> to <b className="tabular-nums">{r.confidence}</b>,
            so this requirement now sits in <b>{QUADRANT[r.quadrant].label}</b>.
          </p>
          <ul className="mt-3 flex list-disc flex-col gap-1 pl-5 text-[14px] text-ink-2">
            {r.challenge.issues.map((i) => <li key={i.text}>{i.text} <span className="text-ink-3">(−{i.penalty})</span></li>)}
          </ul>
        </section>
      )}

      <Section title="From customer voice to requirement">
        <Ladder r={r} />
      </Section>

      <div className="grid gap-6 xl:grid-cols-2">
        <Section title="Priority" aside="How important">
          <div className="mb-5"><ScorePair r={r} size="lg" /></div>
          <FactorBars factors={r.priority_factors} labels={labels} />
        </Section>
        <Section title="Confidence" aside="How well proven">
          <FactorBars factors={r.confidence_factors} labels={labels} />
          <div className="mt-6">
            <Matrix items={siblings} thresholds={thresholds} vehicle={r.vehicle} selected={r.id} size={420} />
          </div>
        </Section>
      </div>

      <Section title="Customer evidence" aside={`${supports.length} supporting · ${contradicts.length} contradicting · visible to ${viewer.label}`}>
        {hiddenTotal > 0 && (
          <p className="mb-4 border border-dashed border-line bg-mist px-4 py-3 text-[14px] text-ink-2">
            {Object.entries(hidden).map(([m, n]) => `${n} comment${n === 1 ? "" : "s"} from ${MARKET_LABEL[m] ?? m}`).join(", ")} restricted to
            {" "}{Object.keys(hidden).length > 1 ? "those markets'" : "that market's"} product managers and the head of product. This access was logged.
          </p>
        )}
        {supports.length === 0 && hiddenTotal === 0 && <p className="text-[14px] text-ink-3">No customer comments. This requirement rests on survey evidence only.</p>}
        <ul className="flex flex-col gap-4">{supports.slice(0, 8).map((q) => <QuoteItem key={q.id} q={q} />)}</ul>
        {contradicts.length > 0 && (
          <>
            <h4 className="eyebrow mt-6 mb-3">Customers who disagree</h4>
            <ul className="flex flex-col gap-4">{contradicts.slice(0, 3).map((q) => <QuoteItem key={q.id} q={q} />)}</ul>
          </>
        )}
      </Section>

      <div className="grid gap-6 xl:grid-cols-2">
        <Section title="Survey evidence" aside="US 2025: share of lowest answers · CN/EU 2025: mean of 10">
          {r.survey.length === 0 ? (
            <p className="text-[14px] text-ink-3">No survey question maps to this topic yet.</p>
          ) : (
            <table className="w-full text-[13px]">
              <tbody>
                {r.survey.map((s) => (
                  <tr key={s.study + s.market + s.attribute} className="border-t border-line first:border-t-0">
                    <td className="py-2 pr-3">{s.attribute}{s.variant ? ` (${s.variant})` : ""}</td>
                    <td className="py-2 pr-3 text-ink-3">{MARKET_LABEL[s.market]}</td>
                    <td className="py-2 text-right tabular-nums">{s.scale === 7 ? `${Math.round((s.bottom3 ?? 0) * 1000) / 10}% negative` : `${s.mean} / 10`}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
          {r.conflicts.length > 0 && (
            <div className="mt-4 border-l-2 border-validate bg-validate-soft px-4 py-3 text-[14px]">
              <b>Markets disagree.</b>{" "}
              {r.conflicts.map((c) => `${c.attribute}: China ${c.cn} vs Europe ${c.eu}`).join("; ")}. Decide whether this is a global or a market-specific requirement.
            </div>
          )}
        </Section>
        <Section title="Assumptions, uncertainties, contradictions">
          <ul className="flex flex-col gap-2 text-[14px]">
            {r.assumptions.map((a) => <li key={a}><span className="mr-2 bg-validate-soft px-1.5 py-0.5 text-[11px] font-semibold uppercase text-validate">Assumption</span>{a}</li>)}
            {r.uncertainties.map((a) => <li key={a}><span className="mr-2 bg-monitor-soft px-1.5 py-0.5 text-[11px] font-semibold uppercase text-monitor">Uncertainty</span>{a}</li>)}
            {r.contradictions.map((a) => <li key={a}><span className="mr-2 bg-danger-soft px-1.5 py-0.5 text-[11px] font-semibold uppercase text-danger">Contradiction</span>{a}</li>)}
          </ul>
        </Section>
      </div>

      <Section title="Audit trail" aside="Who, when, what changed and why">
        <AuditTimeline events={events} />
      </Section>
    </article>
  );
}

import Link from "next/link";
import { notFound } from "next/navigation";
import { DecisionCard } from "@/components/DecisionCard";
import { Header } from "@/components/Header";
