] as const;

const pct = (x: number) => `${Math.round(x * 100)}%`;

export default async function VehiclePage({ params, searchParams }: PageProps<"/vehicles/[code]">) {
  const { code } = await params;
  const sp = await searchParams;
  const vehicle = getVehicle(code);
  if (!vehicle) notFound();
