                <li key={r.id}>
                  <Link
                    href={`/vehicles/${code}?${qFilter ? `q=${qFilter}&` : ""}req=${r.id}`}
                    className={`grid grid-cols-[1fr_auto] gap-x-4 gap-y-1.5 border-b border-line px-4 py-4 ${on ? "bg-mist shadow-[inset_3px_0_0_var(--color-blue)]" : "hover:bg-mist/60"}`}
