                      <span className="text-[20px] font-medium leading-none">{r.priority}</span>
                      <span className="text-[12px] text-ink-3">conf. {r.confidence}</span>
                    </span>
                    <span className="text-[15px] font-normal leading-snug text-ink">{r.title}</span>
                    <span><QuadrantBadge q={r.quadrant} /></span>
