export default function robots(): MetadataRoute.Robots {
  return { rules: { userAgent: "*", disallow: "/" } };
}

import type { NextConfig } from "next";

// We use the previous rendering model (no Cache Components): every page reads fresh data
// from SQLite on each request. Simpler for three people working in parallel.
const nextConfig: NextConfig = {
  cacheComponents: false,
  serverExternalPackages: ["better-sqlite3"],
  // Ship the demo database snapshot with every server function (used on Vercel, see lib/db.ts).
  outputFileTracingIncludes: {
    "/**": ["./data/pmw.sqlite"],
  },
  poweredByHeader: false,
  async headers() {
    return [
      {
        source: "/:path*",
        headers: [{ key: "X-Robots-Tag", value: "noindex, nofollow, noarchive, nosnippet, noimageindex" }],
      },
    ];
  },
  turbopack: {
    rules: {
      "*.css": {
        loaders: ["@tailwindcss/turbopack"],
        as: "*.css",
      },
    },
  },
};

export default nextConfig;

import Database from "better-sqlite3";
import fs from "node:fs";
import path from "node:path";

// Local: the pipeline writes ../db/pmw.sqlite (`cd pipeline && uv run pmw build`).
// Vercel: the app ships a snapshot in web/data/pmw.sqlite (`npm run snapshot`). The app folder is read-only there,
// so the snapshot is copied to /tmp on first use. Decisions made on the hosted demo live in that copy and
// reset when Vercel starts a fresh server instance.
function resolveDbPath(): string {
  if (process.env.PMW_DB) return process.env.PMW_DB;
  const snapshot = path.join(process.cwd(), "data", "pmw.sqlite");
  if (process.env.VERCEL) {
    const tmp = path.join("/tmp", "pmw.sqlite");
    if (!fs.existsSync(tmp)) fs.copyFileSync(snapshot, tmp);
    return tmp;
  }
  const local = path.join(process.cwd(), "..", "db", "pmw.sqlite");
  return fs.existsSync(local) ? local : snapshot;
}

const g = globalThis as unknown as { __pmwDb?: Database.Database };

export function db(): Database.Database {
  if (!g.__pmwDb) {
    const d = new Database(resolveDbPath(), { fileMustExist: true });
    d.pragma("journal_mode = WAL");
    g.__pmwDb = d;
  }
  return g.__pmwDb;
}

export function parse<T>(json: string | null | undefined, fallback: T): T {
  if (!json) return fallback;
  try {
    return JSON.parse(json) as T;
  } catch {
    return fallback;
  }
}

export function nowIso(): string {
  return new Date().toISOString().replace(/\.\d{3}Z$/, "+00:00");
}

